async function mount(host){dispose();const g=generation,project=v2Cloud.projectId;host.innerHTML='<div class="w-card">Loading project process…</div>';try{const model=await v2Preview.plantRequest('process-v2-read');if(g!==generation||!host.isConnected||project!==v2Cloud.projectId)return;const frame=document.createElement('iframe');frame.title='Project process';frame.style.cssText='width:100%;height:calc(100dvh - 135px);min-height:620px;border:0;border-radius:24px;background:var(--paper)';const session=crypto.randomUUID();let revision=model.revision,queue=Promise.resolve();const listener=e=>{const m=e.data;if(e.source!==frame.contentWindow||e.origin!==location.origin||m?.session!==session)return;if(m.type==='studioh-process-dirty'){mounted.pending=true;return}if(m.type==='studioh-process-clean'){mounted.pending=false;return}if(m.type!=='studioh-process-save')return;queue=queue.then(async()=>{let response={type:'studioh-process-saved',session,id:m.id};try{if(g!==generation||project!==v2Cloud.projectId||!host.isConnected)throw Error('Project changed. Reopen Process.');if(v2Cloud.readOnly)throw Error('This project is view only.');const result=await v2Preview.plantRequest('process-v2-save',{process:m.process,revision});revision=result.revision;if(g!==generation||project!==v2Cloud.projectId)throw Error('Project changed during save.');await v2Preview.capture();await v2Cloud.flush();response.result=result}catch(err){response.error=err.message||String(err)}frame.contentWindow?.postMessage(response,location.origin)})};window.addEventListener('message',listener);mounted={listener,pending:false};const initial={...model,origin:location.origin,readOnly:!!v2Cloud.readOnly,demo:!!v2Cloud.demo,session};frame.srcdoc=PROCESS_PAGE.replace('/*PROCESS_DATA*/null',JSON.stringify(initial).replace(/</g,'\u003c'));const review=document.createElement("div");review.style.cssText="padding:0 0 10px;text-align:right";const link=document.createElement("a");link.href="/reviews/process-master-r1/";link.target="_blank";link.rel="noopener";link.className="quiet";link.textContent="Review master process draft ↗";review.append(link);host.replaceChildren(review,frame)}catch(err){if(g===generation&&host.isConnected){host.innerHTML='<div class="w-card"><h2>Process could not load</h2><p></p><button class="action">Try again</button></div>';host.querySelector('p').textContent=err.message;host.querySelector('button').onclick=()=>mount(host)}}}
